package com.genealogy.review.repository;
import com.genealogy.review.repository.mybatis.ReviewTaskQueryMapper; import com.genealogy.review.repository.query.ReviewTaskQueryRow; import org.springframework.stereotype.Repository; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Repository @Transactional(readOnly=true) public class ReviewTaskQueryRepository { private final ReviewTaskQueryMapper mapper; public ReviewTaskQueryRepository(ReviewTaskQueryMapper mapper){this.mapper=mapper;} public QueryPage search(ReviewTaskQueryCriteria criteria,int pageNo,int pageSize){long total=mapper.count(criteria);if(total==0)return new QueryPage(List.of(),0);long offset=Math.multiplyExact((long)Math.max(0,pageNo-1),pageSize);return new QueryPage(mapper.search(criteria,offset,pageSize).stream().map(this::pair).toList(),total);} public Optional<ReviewTaskPair> findByTaskId(Long taskId){return Optional.ofNullable(mapper.findByTaskId(taskId)).map(this::pair);} public List<ReviewTaskPair> findHistory(Long clanId,String targetType,Long targetId,int limit){return mapper.findHistory(clanId,targetType,targetId,Math.max(1,limit)).stream().map(this::pair).toList();} private ReviewTaskPair pair(ReviewTaskQueryRow r){return new ReviewTaskPair(r.task(),r.record());} public record ReviewTaskPair(com.genealogy.review.entity.CheckTaskEntity task,com.genealogy.review.entity.AuditRecordEntity record){} public record QueryPage(List<ReviewTaskPair> records,long total){public QueryPage{records=records==null?List.of():List.copyOf(records);}} }
